/* هل يوافق هذا التاريخ السنة المختارة حالياً؟ (يُستخدم في الشاشات التي لا يوجد لها فلتر تاريخ خاص بها، مثل لوحة التحكم) */
function matchYear(dateStr){
  if(selectedYearFilter==='all') return true;
  return String(dateStr||'').slice(0,4)===String(selectedYearFilter);
}
/* نفس فلتر السنة العام، لكن مخصص لفواتير الدورات: يعتمد على تاريخ صدور الفاتورة (receiptIssueDate)
   بدل تاريخ تسجيل العميل، اتساقاً مع الإقرار الضريبي الذي يحتسب حسب تاريخ الفاتورة فعلياً.
   الفواتير التي لم يُدخل لها تاريخ إصدار بعد تبقى ظاهرة دائماً (بغض النظر عن السنة المختارة)
   حتى لا تختفي من الشاشة قبل استكمال بياناتها. */
function matchInvoiceYear(c){
  if(selectedYearFilter==='all') return true;
  if(!c.receiptIssueDate) return true;
  return String(c.receiptIssueDate).slice(0,4)===String(selectedYearFilter);
}
/* تجميع كل السنوات الموجودة فعلياً في بيانات البرنامج (عملاء، حركات مالية، دورات، مخزون حقائب، تحويلات شركات) */
function collectAllYears(){
  const years = new Set();
  const grab = (arr, key)=>{ (arr||[]).forEach(x=>{ const y = String((x&&x[key])||'').slice(0,4); if(/^\d{4}$/.test(y)) years.add(y); }); };
  grab(clients,'date'); grab(vaultTx,'date'); grab(courseSessions,'date'); grab(bagStock,'date');
  if(typeof companyTransfers!=='undefined') grab(companyTransfers,'date');
  return Array.from(years).sort((a,b)=>b.localeCompare(a));
}
function populateYearFilterSelect(){
  const sel = $('#year-filter');
  if(!sel) return;
  const years = collectAllYears();
  if(selectedYearFilter!=='all' && !years.includes(selectedYearFilter)) selectedYearFilter = 'all';
  sel.innerHTML = `<option value="all">كل السنوات (المدة كلها)</option>` + years.map(y=>`<option value="${y}">سنة ${y}</option>`).join('');
  sel.value = selectedYearFilter;
}
/* يضبط كل حقول (من/إلى تاريخ) في كل شاشات البرنامج على حدود السنة المختارة، ثم يعيد رسم كل الشيتات والتقارير */
function applyYearFilterToAllViews(){
  const from = selectedYearFilter==='all' ? '' : `${selectedYearFilter}-01-01`;
  const to = selectedYearFilter==='all' ? '' : `${selectedYearFilter}-12-31`;
  YEAR_FILTER_DATE_PAIRS.forEach(([f,t])=>{
    const fe = $('#'+f), te = $('#'+t);
    if(fe) fe.value = from;
    if(te) te.value = to;
  });
  // كل شاشة تُعاد رسمها بمعزل عن الأخرى: لو شاشة واحدة رمت استثناء غير متوقع، الباقي يكمل عادي
  // بدل ما يتوقف كل شيء بعدها (وهو ما كان يجعل اختيار سنة يبدو بلا أي تأثير على الإطلاق).
  const safeRender = (fn, label)=>{ try{ if(typeof fn==='function') fn(); }catch(e){ console.error(`applyYearFilterToAllViews: فشلت "${label}"`, e); } };
  safeRender(typeof refreshFilterOptions!=='undefined' && refreshFilterOptions, 'refreshFilterOptions');
  safeRender(typeof renderDashboard!=='undefined' && renderDashboard, 'renderDashboard');
  safeRender(typeof renderTable!=='undefined' && renderTable, 'renderTable');
  safeRender(typeof renderVault!=='undefined' && renderVault, 'renderVault');
  safeRender(typeof renderBags!=='undefined' && renderBags, 'renderBags');
  safeRender(typeof renderOwnBagClients!=='undefined' && renderOwnBagClients, 'renderOwnBagClients');
  safeRender(typeof renderClientBagPurchases!=='undefined' && renderClientBagPurchases, 'renderClientBagPurchases');
  safeRender(typeof renderCourses!=='undefined' && renderCourses, 'renderCourses');
  safeRender(typeof renderCourseInvoices!=='undefined' && renderCourseInvoices, 'renderCourseInvoices');
  safeRender(typeof renderMissingCourse!=='undefined' && renderMissingCourse, 'renderMissingCourse');
  safeRender(typeof renderCompanies!=='undefined' && renderCompanies, 'renderCompanies');
  safeRender(typeof renderReports!=='undefined' && renderReports, 'renderReports');
  safeRender(typeof renderAccounting!=='undefined' && renderAccounting, 'renderAccounting');
  safeRender(typeof renderAuditLog!=='undefined' && renderAuditLog, 'renderAuditLog');
}
let yearFilterListenerBound = false;
function initYearFilter(){
  populateYearFilterSelect();
  applyYearFilterToAllViews();
  // ملاحظة مهمة: هذه الدالة تُستدعى أكثر من مرة (عند فتح البرنامج أولاً، وأيضاً بعد كل
  // مزامنة خلفية تجلب تغييرات فعلية من السحابة — راجع renderAllViewsAfterLoad). بدون هذا
  // الحارس (guard)، كان يُضاف مستمع 'change' جديد على #year-filter في كل مرة دون إزالة
  // القديم، فيتراكم عدد المستمعين مع الوقت ويتكرر تنفيذ applyYearFilterToAllViews() ورسالة
  // التنبيه عدة مرات لكل اختيار سنة واحد — وهو ما كان يجعل فلتر السنة يبدو "معطَّلاً" أو بطيئاً.
  if(yearFilterListenerBound) return;
  yearFilterListenerBound = true;
  $('#year-filter').addEventListener('change', e=>{
    selectedYearFilter = e.target.value;
    localStorage.setItem('selectedYearFilter', selectedYearFilter);
    applyYearFilterToAllViews();
    showToast(selectedYearFilter==='all' ? 'تم عرض كل السنوات (المدة كلها)' : `تم تحديد سنة العمل: ${selectedYearFilter}`);
  });
}
